package com.angle.trading.security;import jakarta.servlet.http.*;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.security.web.access.AccessDeniedHandler;import org.springframework.stereotype.Component;import java.io.IOException;@Componentpublic class CustomAccessDeniedHandler        implements AccessDeniedHandler {    private static final Logger log =            LoggerFactory.getLogger(CustomAccessDeniedHandler.class);    @Override    public void handle(HttpServletRequest request,                       HttpServletResponse response,                       org.springframework.security.access.AccessDeniedException ex)            throws IOException {        log.info("Access Denied");        response.sendRedirect("/access-denied");    }}